const headers={'content-security-policy':"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",'referrer-policy':'no-referrer','x-content-type-options':'nosniff','x-frame-options':'DENY','permissions-policy':'camera=(), microphone=(), geolocation=()','strict-transport-security':'max-age=31536000; includeSubDomains'};
const json=(d,s=200)=>new Response(JSON.stringify(d),{status:s,headers:{'content-type':'application/json; charset=utf-8',...headers}});
async function proxy(request,env){if(!env.BACKEND_URL||!env.ADMIN_API_TOKEN)return json({error:'CRM no configurado.'},503);const url=new URL(request.url),target=`${env.BACKEND_URL}${url.pathname.replace('/api','/api/admin')}`;const init={method:request.method,headers:{authorization:`Bearer ${env.ADMIN_API_TOKEN}`,'x-admin-role':env.CRM_ROLE||'admin','content-type':'application/json'}};if(!['GET','HEAD'].includes(request.method))init.body=await request.text();try{const r=await fetch(target,init);return new Response(r.body,{status:r.status,headers:{'content-type':r.headers.get('content-type')||'application/json',...headers}})}catch(e){console.error('proxy failed',e);return json({error:'Backend no disponible.'},503)}}
export default{async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith('/api/'))return proxy(request,env);const asset=ASSETS[url.pathname]||ASSETS['/'];return new Response(asset.body,{headers:{'content-type':asset.type,'cache-control':url.pathname==='/'?'no-cache':'public, max-age=3600',...headers}})}};
